ALTER PROCEDURE BAZAR_INC_UPD_MOBILE_BILLS_JSON
    @JsonData NVARCHAR(MAX),  
    @LINE VARCHAR(50),   -- LINE  
    @BILLDATE DATETIME2  
AS  
BEGIN  
    SET NOCOUNT ON;  
    
    --SET @JsonData = REPLACE(@JsonData,'\','');  
    -- Remove backslashes only if present (double-encoded JSON)  
    IF @JsonData LIKE '%\\%'  
    BEGIN  
        SET @JsonData = REPLACE(@JsonData,'\','');  
    END  
    -------------------------------------------------------------------  
    -- Build #Source from JSON + ItemMaster  
    -------------------------------------------------------------------  
    IF OBJECT_ID('tempdb..#Source') IS NOT NULL DROP TABLE #Source;  
  
    SELECT   
        j.ItemCode, j.ItemName, j.Rate, j.Qty, j.packing_qty, j.Amount,  
        j.BillNo, @BILLDATE AS BILLDATE, @LINE AS LINE, j.ShopName,  
        ISNULL(j.Area,@LINE) AS Area, isnull(j.Ret_Qty,0) as Ret_Qty,  
        j.DiscountPercent, j.Offer_Item, j.Offer_Rate, j.Offer_Qty,  
        j.Salesman, j.paymentmode, j.MobileOrderDate,j.mobile
    INTO #Source  
    FROM (  
        SELECT   
            ItemCode, ItemName, Rate, Qty, packing_qty, Amount, BillNo, ShopName,  
            Line, Area, Ret_Qty, DiscountPercent, Offer_Item, Offer_Rate, Offer_Qty,  
            Salesman, paymentmode, MobileOrderDate ,Mobile 
        FROM OPENJSON(@JsonData)  
        WITH (  
            ItemCode INT,  
            ItemName NVARCHAR(100),  
            Rate MONEY,  
            Qty INT,  
            packing_qty VARCHAR(20),  
            Amount MONEY,  
            BillNo NVARCHAR(50),  
            ShopName NVARCHAR(100),  
            Line NVARCHAR(50),  
            Area NVARCHAR(50),  
            Ret_Qty MONEY,  
            DiscountPercent MONEY,  
            Offer_Item NVARCHAR(100),  
            Offer_Rate MONEY,  
            Offer_Qty INT,  
            Salesman NVARCHAR(50),  
            paymentmode NVARCHAR(20),  
            MobileOrderDate DATETIME2,
            Mobile VARCHAR(10)
        )  
    ) j    
       -------------------------------------------------------------------  
    -- Build #Previous for stock adjustment  BEFORE UPDATING 
    -------------------------------------------------------------------  
    --IF OBJECT_ID('tempdb..#Previous') IS NOT NULL DROP TABLE #Previous;  
  
    --SELECT s.ItemCode, s.ItemName, s.BillNo, s.ShopName,  
    --       s.Qty AS NewPackets, b.Packets AS PreviousPackets,isnull(s.Ret_Qty,0) Ret_Qty,isnull(b.Damages,0) as Prev_Ret_Qty
    --INTO #Previous  
    --FROM #Source s  
    --INNER JOIN Bazar_Mobile_Bills b  
    --    ON b.ItemCode = s.ItemCode  
    --   AND b.ItemName = s.ItemName  
    --   AND b.Line = @LINE  
    --   AND b.ShopName = s.ShopName  
    --   AND b.BillNumber = s.BillNo  
    --   AND CAST(b.BillDate AS DATE) = CAST(@BILLDATE AS DATE);  
  
  --SELECT * FROM #SOURCE
  --SELECT * FROM #PREVIOUS

            ---this will update negative stock with zero. TODO: need to delete this once the stock is stable.
           -- update BAZAR_ItemMaster set stock=0 where stock<0 AND SHOPNAME=@LINE;

          BEGIN TRY
            BEGIN TRAN;

            DECLARE 
                @BillNumber  INT,@ItemCode INT,
                @ItemName NVARCHAR(100),
                @Qty INT,@OfferItemName nvarchar(100),@Offer_Qty INT,@Ret_Qty INT,
                @ExistingQty INT,@ExistingOfferQty INT,@ExistingRetQty INT;

            DECLARE src_cur CURSOR LOCAL FAST_FORWARD FOR
            SELECT BillNo, ItemCode, ItemName, Qty,Offer_Item,Offer_Qty, Ret_Qty FROM #Source;
            
            OPEN src_cur;
            FETCH NEXT FROM src_cur INTO @BillNumber, @ItemCode, @ItemName, @Qty,@OfferItemName,@Offer_Qty, @Ret_Qty;
            WHILE @@FETCH_STATUS = 0
            BEGIN
                ---- Find an existing matching bill row (match on billnumber, billdate, itemcode, itemname)
                --SELECT TOP (1) @ExistingQty = ISNULL(Packets, 0), @ExistingRetQty = ISNULL(Damages, 0),@ExistingOfferQty=ISNULL(OFFER_QTY,0)
                --FROM dbo.Bazar_Mobile_Bills  WHERE BillNumber = @BillNumber
                --  AND CONVERT(date, BillDate) = CONVERT(date, @BillDate) and LINE=@LINE AND ItemCode = @ItemCode AND ItemName = @ItemName;
                if not exists (select 'x' from  dbo.Bazar_Mobile_Bills  WHERE BillNumber = @BillNumber
                  AND CONVERT(date, BillDate) = CONVERT(date, @BillDate) and LINE=@LINE AND ItemCode = @ItemCode AND ItemName = @ItemName)
                  begin
                              print 'New Item processing...' + cast(@BillNumber as varchar(10)) + ' -> ' + @ItemName + ' Qty = ' + cast(@Qty as varchar(10))
                                UPDATE im SET Stock = ISNULL(im.Stock,0) - isnull(@Qty,0) + isnull(@Ret_Qty,0),ActionDate = GETDATE(),USERNAME='FROM SP2'
                                FROM dbo.BAZAR_ItemMaster im
                                WHERE im.ItemCode = @ItemCode AND im.ItemName = @ItemName  AND SHOPNAME=@LINE and im.Status='Active';

                                if isnull(@Offer_Qty,0) > 0 
                                begin
                                    UPDATE im SET Stock = isnull(im.Stock,0) - isnull(@Offer_Qty,0),ActionDate = GETDATE() ,USERNAME='FROM SP2'
                                    FROM dbo.BAZAR_ItemMaster im WHERE im.ItemName = @OfferItemName AND SHOPNAME=@LINE and im.Status='Active';
                               end
                  end
                  else
                  begin
                        print 'Item already added...' + cast(@BillNumber as varchar(10)) + ' -> ' + @ItemName + ' Qty = ' + cast(@Qty as varchar(10))
                  end
                --IF @ExistingQty IS NOT NULL
                --BEGIN
                --    -- Revert previous effect and apply new values:
                --    -- stock = stock + previous_sold - new_sold - previous_return + new_return
                --    UPDATE im SET Stock = isnull(im.Stock,0) + @ExistingQty - isnull(@Qty,0) - @ExistingRetQty + isnull(@Ret_Qty,0),
                --    ActionDate = GETDATE()  FROM dbo.BAZAR_ItemMaster im
                --    WHERE im.ItemCode = @ItemCode AND im.ItemName = @ItemName AND SHOPNAME=@LINE and im.Status='Active';

                --   UPDATE im SET Stock = isnull(im.Stock,0) + @ExistingOfferQty - isnull(@Offer_Qty,0) - @ExistingRetQty + isnull(@Ret_Qty,0),
                --    ActionDate = GETDATE()  FROM dbo.BAZAR_ItemMaster im
                --    WHERE im.ItemName = @OfferItemName AND SHOPNAME=@LINE and im.Status='Active';
                --END
                --ELSE
                --BEGIN
                --    -- New bill row: apply new sale/return
                --    UPDATE im SET Stock = ISNULL(im.Stock,0) - isnull(@Qty,0) + isnull(@Ret_Qty,0),ActionDate = GETDATE()
                --    FROM dbo.BAZAR_ItemMaster im
                --    WHERE im.ItemCode = @ItemCode AND im.ItemName = @ItemName  AND SHOPNAME=@LINE and im.Status='Active';

                --   UPDATE im SET Stock = isnull(im.Stock,0) - isnull(@Offer_Qty,0),ActionDate = GETDATE()  
                --   FROM dbo.BAZAR_ItemMaster im WHERE im.ItemName = @OfferItemName AND SHOPNAME=@LINE and im.Status='Active';
                --END
                -- reset and fetch next
                --SET @ExistingQty = NULL; SET @ExistingRetQty = NULL;
                --set @BillNumber=0; set @ItemCode=0; set @ItemName=''; set @Qty=0; set @OfferItemName=''; set @Offer_Qty=0; set @Ret_Qty=0;
                FETCH NEXT FROM src_cur INTO @BillNumber, @ItemCode, @ItemName, @Qty,@OfferItemName,@Offer_Qty, @Ret_Qty;
            END

            CLOSE src_cur;
            DEALLOCATE src_cur;

            COMMIT TRAN;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> 0 ROLLBACK TRAN;
            DECLARE @ErrMsg NVARCHAR(4000) = ERROR_MESSAGE();
            RAISERROR('%s',16,1,@ErrMsg);
        END CATCH;
    -------------------------------------------------------------------  
    -- MERGE into Bazar_Mobile_Bills
    -------------------------------------------------------------------  
    print '>>>> updating Bazar_Mobile_Bills <<<<<'
  --SELECT * FROM #SOURCE

    MERGE Bazar_Mobile_Bills AS target  
    USING #Source AS source  
        ON target.ItemName = source.ItemName  
       AND target.Line = source.Line  
       --AND target.Area = source.Area 
       AND target.ShopName = source.ShopName    --we can skip shopname validation since Billnumber is unique for each bill
       AND target.BillNumber = source.BillNo  
       AND CAST(target.BillDate AS DATE) = CAST(source.BillDate AS DATE)  
    WHEN MATCHED THEN  
        UPDATE SET   
            target.Rate = source.Rate,  
            target.Packets = source.Qty,  
            target.Qty = source.packing_qty,  
            target.Amount = source.Rate * source.Qty,  
            target.Username = 'From_Mobile',  
            target.Damages = isnull(source.Ret_Qty,0),  
            target.Discount = source.DiscountPercent,  
            target.Offer_Item = source.Offer_Item,  
            target.Offer_Rate = isnull(source.Offer_Rate,0),  
            target.Offer_Qty = source.Offer_Qty,  
            target.Salesman = source.Salesman,  
            target.BillDate = source.BillDate,  
           target.MobileOrderDate = source.MobileOrderDate,  
            target.Payment_Mode = source.paymentmode,  
            target.ActionDate = GETDATE(),  
            target.Cust_Mobile = source.Mobile  
    WHEN NOT MATCHED THEN  
        INSERT (ItemCode, ItemName, Rate, Packets, Qty, Amount, BillNumber, BillDate,  
                Line,Area, ShopName, Username, PRATE, Damages, Discount,  
                Offer_Item, Offer_Rate, Offer_Qty, Salesman, Payment_Mode, MobileOrderDate, ActionDate,Cust_Mobile)  
        VALUES (source.ItemCode, source.ItemName, source.Rate, source.Qty, source.packing_qty,  
                source.Rate * source.Qty, source.BillNo, source.BillDate, source.Line, source.Area, source.ShopName,  
                'From_Mobile', 0, isnull(source.Ret_Qty,0), source.DiscountPercent,  
                source.Offer_Item, isnull(source.Offer_Rate,0), source.Offer_Qty, source.Salesman,  
                source.paymentmode, source.MobileOrderDate, GETDATE(),source.Mobile);  

    --print '>>>> END of updating Bazar_Mobile_Bills <<<<<'
    -------------------------------------------------------------------  
    -- Stock adjustment for matched rows , commenting as there no much scope for updating items from mobile. 
    -------------------------------------------------------------------  
    --UPDATE im  
    --SET im.Stock = im.Stock + p.PreviousPackets - p.NewPackets - p.Prev_Ret_Qty + p.Ret_Qty,  
    --    im.ActionDate = GETDATE()  
    --FROM BAZAR_ItemMaster im  
    --INNER JOIN #Previous p ON im.ItemCode = p.ItemCode AND im.ItemName = p.ItemName;      
    ---------------------------------------------------------------------  
    ---- Stock adjustment for newly inserted rows  
    ---------------------------------------------------------------------  
    --UPDATE im  
    --SET im.Stock = im.Stock - s.Qty + isnull(s.Ret_Qty,0),  
    --   -- im.Username = s.Username,  
    --    im.ActionDate = GETDATE()  
    --FROM BAZAR_ItemMaster im  
    --INNER JOIN #Source s ON im.ItemCode = s.ItemCode AND im.ItemName = s.ItemName  
    --WHERE NOT EXISTS (  
    --    SELECT 1 FROM #Previous p WHERE p.ItemCode = s.ItemCode AND p.ItemName = s.ItemName  
    --)
    -------------------------------------------------------------------  
    -- update discount = 0 for non eligible items   
    UPDATE Bazar_Mobile_Bills SET DISCOUNT=0 where area=@LINE and billdate=@BILLDATE and discount > 0   
  and billnumber not in (  
  select billnumber from Bazar_Mobile_Bills where area=@LINE and billdate=@BILLDATE and discount > 0   
  group by Billnumber,Area Having sum(amount) >=5000 )  
  
  -------Insert or Update into Cust Master, to maintain separate table for all customer details.
  --SELECT Distinct s.Shopname, s.Mobile INTO #CustomerDetails  FROM #Source s  where s.Line = @LINE and isnull(s.Shopname,'') <> ''  
    MERGE BAZAR_CUST_MASTER AS Target
    using (SELECT Distinct s.Line,s.Shopname, s.Mobile  FROM #Source s  where s.LINE = @LINE and isnull(s.Shopname,'') <> '') as Source 
    ON Target.CustomerName=Source.ShopName and
    Target.Line=Source.Line And
    Target.Mobile=Source.Mobile
    WHEN MATCHED THEN
        UPDATE SET  Target.Mobile=Source.Mobile,Target.ACTIONDATE=GETDATE()
        WHEN NOT MATCHED AND  Source.ShopName <> '' THEN  
        INSERT (LINE,CUSTOMERNAME,MOBILE,STATUS) 
        VALUES (Source.Line,Source.Shopname,Source.Mobile,'Active');

SELECT 1 AS RESULT;  
END  